// Generated by scripts/i18n_batch.js merge; edit the line here or in es.ts.
/* eslint-disable */
export const PART: Readonly<Record<string, string>> = {
 "gon7cr2nsz": "La HPB es un crecimiento no canceroso de la próstata que se vuelve cada vez más común con la edad y causa síntomas urinarios (orinar seguido, chorro débil, levantarse de noche al baño) porque aprieta la uretra. Es un padecimiento distinto del cáncer de próstata, aunque los dos pueden darse al mismo tiempo y algunos de los mismos valores de laboratorio (como el APE) pueden cambiar por cualquiera de los dos, una fuente común de confusión que se explica directamente en la investigación de Salud de la próstata de esta app.",
 "15m68i5744z": "BRCA2 es un gen que normalmente ayuda a reparar el ADN dañado; una mutación heredada en él es conocida sobre todo por subir el riesgo de cáncer de mama y de ovario, pero también sube de forma medible el riesgo de cáncer de próstata, y se asocia con una enfermedad más agresiva, en los hombres que la tienen. Por eso los antecedentes familiares de cáncer relacionado con BRCA2, de cualquier lado de la familia, son información útil para abogar por uno mismo en la salud de la próstata en específico, no solo para los parientes que más se asocian con el gen.",
 "b5fcny8p3w": "La TCC es una forma estructurada de terapia psicológica que funciona identificando y cambiando patrones de pensamiento y conductas que no ayudan. Una versión específica, la TCC-I (para el insomnio), es hoy el tratamiento de primera línea que recomiendan las guías para el insomnio crónico, antes que los medicamentos para dormir, y se explica directamente en la investigación de Sueño y salud de esta app.",
 "25t9dvc71y0": "La prueba de anticuerpos anti CCP (anti péptido cíclico citrulinado) busca un marcador inmune específico que es más propio de la artritis reumatoide que la prueba más antigua de factor reumatoide (FR), o sea que un resultado positivo tiene menos probabilidad de venir de una causa sin relación. Puede salir positiva años antes de que aparezca cualquier síntoma en las articulaciones, lo que la hace un dato útil para abogar por uno mismo para cualquier persona con antecedentes familiares de AR o con síntomas articulares sin explicación.",
 "1oqsbpdjdgd": "El CGRP es una molécula de señalización que se suelta alrededor de los vasos sanguíneos y los nervios y que tiene un papel directo y documentado en desatar los ataques de migraña. Los medicamentos más nuevos para la migraña (inhibidores del CGRP, entre ellos los \"gepantes\" y los anticuerpos monoclonales inyectables) funcionan bloqueando directamente el CGRP o su receptor, un mecanismo más dirigido que el de los tratamientos más antiguos y generales, y se explican en la investigación de Migraña de esta app.",
 "9qr37i0ukc": "Una química sanguínea completa (CMP) es un perfil de sangre estándar que mide unos 14 marcadores a la vez, entre ellos la función renal (creatinina, TFGe), las enzimas del hígado, el azúcar en la sangre y electrolitos como el potasio y el sodio. Es una prueba de base común para vigilar el funcionamiento general de los órganos, y algunos de sus valores pueden cambiar por padecimientos o medicamentos que a primera vista no parecen tener relación directa con los riñones o el hígado, algo que se explica directamente en la investigación de esta app sobre abogar por uno mismo.",
 "hrit180gpo": "El CPAP es un aparato que manda un flujo constante de aire a presión por una mascarilla que se usa al dormir, para que la vía respiratoria no se cierre, el tratamiento estándar de primera línea para la apnea obstructiva del sueño. La apnea del sueño tiene vínculos documentados en los dos sentidos con varios padecimientos que sigue esta app, entre ellos el hígado graso, que se explica directamente en la investigación de esa categoría.",
 "19gek31izld": "La CAD es una complicación peligrosa, que puede poner en riesgo la vida, y que aparece cuando el cuerpo tiene tan poca insulina que no puede usar el azúcar de la sangre como energía y empieza a desarmar grasa en su lugar, lo que acumula cetonas ácidas en la sangre. Puede formarse en cuestión de horas, casi siempre en la diabetes tipo 1, y existen \"reglas para días de enfermedad\" específicas justo para detectarla y prevenirla cuando uno está enfermo, que se explican directamente en la investigación de Diabetes tipo 1 de esta app.",
 "1dj7xmig0f6": "Los FARME son un tipo de medicamento que actúa sobre el proceso inmune de fondo que impulsa la artritis reumatoide y frena o evita el daño a las articulaciones, en lugar de solo aliviar el dolor o la inflamación como haría un analgésico sin receta. Está documentado que empezar un FARME temprano, en los primeros meses de síntomas, da resultados a largo plazo medibles y mejores que empezar el mismo tratamiento después, la \"ventana de oportunidad\" que se explica directamente en la investigación de Artritis reumatoide de esta app.",
 "26jfe94ne8k": "El VEB es un virus muy común, la causa de la mononucleosis infecciosa, que la gran mayoría de los adultos ha tenido en algún momento. La investigación encontró un parecido molecular específico entre ciertas proteínas del VEB y los tejidos del propio cuerpo, un ejemplo documentado de mimetismo molecular y uno de los mecanismos que se proponen como detonante de varias enfermedades autoinmunes, entre ellas la esclerosis múltiple, que se explica directamente en la investigación de Esclerosis múltiple de esta app.",
 "1mng2n8tgpf": "El FIB-4 es una puntuación calculada (con la edad y tres valores de laboratorio de rutina relacionados con el hígado que ya vienen en un perfil estándar) que estima la probabilidad de cicatrización importante del hígado, o fibrosis, sin necesidad de una biopsia. Las guías clínicas lo recomiendan como primer paso de revisión para el hígado graso justo porque cuesta poco y usa análisis que mucha gente ya tiene, aunque su precisión ha salido irregular en algunos estudios, una limitación que se explica directamente en la investigación de Hígado graso de esta app.",
 "s0d5rvuqdx": "El TMF pasa heces procesadas de un donante sano y revisado al tubo digestivo de otra persona, con la intención de cambiar su microbiota intestinal. Ya es un tratamiento bien establecido y reconocido por la FDA para la infección recurrente por C. difficile, y se está estudiando activamente, con resultados mixtos según el padecimiento, para varios otros que cubre esta app, con datos de ensayos alentadores para la colitis ulcerosa y resultados no concluyentes para el SII.",
 "1o7easelhmu": "GI es la abreviatura común de gastrointestinal, todo el sistema digestivo del estómago a los intestinos. Aparece todo el tiempo en la investigación de esta app sobre salud intestinal, microbiota y cada padecimiento (un \"síntoma GI\", el \"tubo GI\" o un \"sangrado GI\") como una abreviatura sencilla para el sistema digestivo, no como un concepto médico aparte.",
 "ifwbsnfxvy": "Los agonistas del receptor de GLP-1 (semaglutida y medicamentos parecidos) funcionan imitando una hormona natural del intestino que aumenta la liberación de insulina, hace más lenta la digestión y reduce el apetito. Las guías actuales ya recomiendan este tipo de medicamento, junto con los inhibidores de SGLT2, como tratamiento farmacológico de primera línea para muchas personas con diabetes tipo 2, sobre todo para quienes ya tienen enfermedad del corazón o de los riñones, justo por los beneficios documentados de protección a los órganos que van más allá del control del azúcar.",
 "21fclzm65aa": "Los genes HLA producen proteínas en la superficie de las células que el sistema inmune usa para distinguir el tejido del propio cuerpo de los invasores de fuera. Ciertas variantes heredadas de HLA son el mayor factor de riesgo genético conocido para desarrollar enfermedad celíaca, enfermedad de Graves y varios otros padecimientos autoinmunes que cubre esta app, aunque tener la variante no garantiza desarrollar la enfermedad, ya que la mayoría de quienes la tienen nunca la desarrollan.",
 "8cxyv94h74": "El HOMA-IR es una puntuación que se calcula con dos valores de laboratorio de rutina en ayunas, la glucosa y la insulina, y se usa sobre todo en investigación para estimar qué tan resistente a la insulina es el cuerpo de alguien. Aparece en toda la investigación de esta app sobre magnesio, cromo, vitamina D y SOP como resultado medido en ensayos de suplementación, una herramienta de investigación más que un diagnóstico clínico de rutina por sí mismo.",
 "1yrfvalua3x": "El IGF-1 es una hormona que da la señal de crecimiento a las células de todo el cuerpo y que tiene una estructura parecida a la insulina, de ahí su nombre. Consumir lácteos sube de forma medible los niveles de IGF-1 en la sangre, un mecanismo documentado que esta app relaciona con que empeoren los síntomas del SOP impulsados por andrógenos y, por separado, con el riesgo de cáncer de próstata, que se explican en la investigación de cada padecimiento.",
 "po0we5dxsz": "La FIV fecunda un óvulo con espermatozoides fuera del cuerpo y luego pasa el embrión que resulta al útero, una de varias opciones de tratamiento de fertilidad. El SOP es una de las principales causas de infertilidad, y la investigación de esta app cubre los resultados de la FIV en la práctica en específico para personas con SOP, no solo el tratamiento de fertilidad en general.",
 "1h94we4jpkj": "Los inhibidores de JAK (tofacitinib, baricitinib, upadacitinib) son un tipo más nuevo de medicamento oral para la artritis reumatoide y otros padecimientos inflamatorios. Un ensayo dedicado a su seguridad encontró más riesgo de infarto, embolia cerebral, cáncer, coágulos, infección grave y muerte en comparación con un tipo de medicamento más antiguo en una población en riesgo, lo que llevó a la FDA a exigir para toda la clase una advertencia en recuadro, su etiqueta de advertencia más fuerte, que se explica directamente en la investigación de Artritis reumatoide de esta app.",
 "1rh2g7n2kqm": "El LDL y el HDL son dos tipos de lipoproteína que llevan el colesterol por la sangre. El LDL (colesterol \"malo\") contribuye directamente a la placa que tapa las arterias cuando sus niveles están altos, mientras que el HDL (colesterol \"bueno\") ayuda a llevarse el colesterol de las paredes de las arterias para eliminarlo. Los dos son valores estándar de un perfil de lípidos, y la investigación de Enfermedad cardiovascular de esta app cubre una base grande de ensayos combinados que muestra que bajar el LDL medido va de la mano con menos riesgo de infarto y embolia cerebral.",
 "wfdpcf4ovo": "NASH (esteatohepatitis no alcohólica) era el nombre establecido para la etapa más avanzada e inflamada del hígado graso. El campo ha ido cambiando a MASH (esteatohepatitis asociada a disfunción metabólica), un cambio de nombre pensado para describir el padecimiento por su causa metabólica y no por lo que no es, sin cambiar la enfermedad de fondo, y que se explica en toda la investigación de Hígado graso de esta app.",
 "p4uebf8dvq": "La TDN es un medicamento de reemplazo de hormona tiroidea hecho de glándula tiroides animal (por lo general de cerdo) seca y procesada, que contiene T4 y T3 en una proporción fija, a diferencia de la levotiroxina sintética, que es solo T4. La investigación de esta app sobre análisis y medicamentos cubre directamente el debate que sigue abierto sobre la TDN y la terapia combinada de T3 y T4, incluidas las dudas sobre la consistencia de un lote a otro que vienen con una fuente biológica y no sintética.",
 "1rnstycs05b": "Los AINE (antiinflamatorios no esteroideos) son un tipo común de medicamento para el dolor y la inflamación, entre ellos el ibuprofeno y el naproxeno, que se consiguen sin receta y con receta. La investigación de esta app cubre los riesgos específicos de cada padecimiento, entre ellos el riesgo documentado de daño renal en la enfermedad renal crónica, que se explica en la investigación de esa categoría.",
 "g5m8hh3wsk": "Una curva de tolerancia a la glucosa (CTOG) mide el azúcar en la sangre al inicio y de nuevo dos horas después de tomar una solución de glucosa estandarizada, y detecta un mal manejo de la glucosa que una glucosa en ayunas sola puede pasar por alto. La investigación de SOP de esta app cubre evidencia directa de que la glucosa en ayunas sola no detectó la intolerancia a la glucosa en la mayoría de los casos de SOP que una CTOG completa sí detectó, una de las razones por las que se recomienda en específico por encima de la glucosa en ayunas sola para ese padecimiento.",
 "d4ghwkziag": "El ALA (ácido alfa linolénico) es el omega 3 de origen vegetal, que está en la linaza y la nuez; el EPA y el DHA son los dos omega 3 de origen marino, que están en el pescado graso y las algas, y por lo general se consideran las formas más activas en el cuerpo. El cuerpo puede convertir el ALA en EPA y DHA, pero con poca eficiencia, un cuello de botella de conversión bien documentado que se explica directamente en la investigación de Nutrientes esenciales de esta app, una de las razones por las que una fuente de omega 3 solo vegetal no da en automático el mismo efecto que una marina.",
 "10yrmu3wl10": "La EAP es el estrechamiento de las arterias que llevan sangre a las piernas (y a veces a otros órganos), causado por el mismo proceso de aterosclerosis de fondo que causa la enfermedad de las arterias coronarias, solo que en otra parte del cuerpo. Tenerla es una señal de un riesgo cardiovascular más amplio, y se explica directamente en la investigación de Enfermedad cardiovascular de esta app junto con sus equivalentes en los riñones y el cerebro.",
 "gzuadkqmo1": "El PASI es una puntuación estandarizada que combina cuánto del cuerpo cubre la psoriasis con qué tan grave se ve (enrojecimiento, grosor, descamación), y se usa para seguir la gravedad de la enfermedad y la respuesta al tratamiento. El \"PASI75\", una mejoría del 75% en esta puntuación, es la marca que usan la mayoría de los ensayos de medicamentos y de estilo de vida para la psoriasis para definir un buen resultado, y se explica directamente en la investigación de Psoriasis de esta app.",
 "2a72y70o7pn": "El APE (antígeno prostático específico) es una proteína que fabrica la próstata y que se mide con un análisis de sangre estándar como herramienta de detección del cáncer de próstata. También puede subir por HPB, prostatitis o variación normal, no solo por cáncer, y por eso las guías actuales tratan la decisión de hacerse la prueba como algo individual, guiado por el médico, y no como una recomendación de rutina para todos, algo que se explica directamente en la investigación de Salud de la próstata de esta app.",
 "12b89q4414v": "La CEP es un padecimiento que causa cicatrización y estrechamiento progresivos de los conductos biliares dentro y fuera del hígado, lo que con el tiempo puede llevar a un daño grave del hígado. Se da bastante más en personas con EII, sobre todo con colitis ulcerosa, que en la población general, y es una de varias complicaciones extraintestinales, efectos que van más allá del intestino, que se explican directamente en la investigación de EII de esta app.",
 "1iivbjg65es": "El PSMA es una proteína que las células del cáncer de próstata tienen en niveles mucho más altos que el tejido sano. Esa diferencia hoy se usa de dos formas: como una herramienta de imagen más sensible para ubicar con exactitud a dónde se ha extendido el cáncer de próstata, y como el blanco de una terapia con radioligandos aprobada por la FDA que se une al PSMA antes de soltar su dosis de radiación directo sobre el cáncer, un enfoque más preciso que un haz externo amplio, que se explica directamente en la investigación de Salud de la próstata de esta app.",
 "1b2qhe5jqcd": "El PTU es un medicamento que reduce la producción de hormona tiroidea y se usa para controlar una tiroides hiperactiva, casi siempre por enfermedad de Graves. Tiene un riesgo raro pero grave de daño al hígado, y por eso la vigilancia regular es parte de la atención estándar mientras se toma, algo que se explica directamente en la investigación de enfermedad de Graves de esta app sobre la vigilancia de los antitiroideos.",
 "257oj4d6zz3": "El sueño MOR (de movimientos oculares rápidos) es una de las etapas principales por las que pasa el cuerpo durante la noche, marcada por sueños vívidos, y se relaciona en específico con fijar la memoria y procesar las emociones. Está junto a las etapas más profundas, no MOR, como parte del ciclo completo de la arquitectura del sueño, que se explica directamente en la investigación de Sueño y salud de esta app.",
 "pyun57nyav": "Los inhibidores de SGLT2 (empagliflozina y medicamentos parecidos) bajan el azúcar en la sangre haciendo que los riñones saquen más glucosa por la orina. Además del control del azúcar, este tipo de medicamento tiene beneficios documentados y aparte de protección para los riñones y el corazón, y por eso las guías actuales lo recomiendan para la enfermedad renal crónica y la insuficiencia cardiaca en específico, no solo para la diabetes, algo que se explica directamente en la investigación de Enfermedad renal crónica de esta app.",
 "fb4q7soo8r": "El SLEDAI (y su versión actualizada, el SLEDAI-2K) es un instrumento formal que califica la actividad del lupus en varios sistemas del cuerpo y da un número específico en lugar de una impresión subjetiva. Una subida de 4 puntos o más respecto a la consulta anterior es la definición formal y estándar de un brote, que se explica directamente en la investigación de Lupus de esta app junto con sus umbrales de remisión y de baja actividad.",
 "2fpjjquhscn": "El TMAO es un compuesto que se produce cuando las bacterias intestinales procesan la colina y la carnitina, nutrientes que están sobre todo en la carne roja y el huevo, y que el hígado luego convierte en TMAO. La investigación encuentra que los niveles altos de TMAO se asocian por sí solos con el riesgo cardiovascular, una conexión documentada entre la microbiota intestinal y la enfermedad del corazón que se explica directamente en la investigación de Enfermedad cardiovascular de esta app.",
 "rz372fzi2a": "La TPMT es una enzima que ayuda al cuerpo a desarmar los medicamentos tiopurínicos (azatioprina y medicamentos parecidos), que se usan seguido para la EII. Las personas con actividad de TPMT baja por naturaleza, un rasgo genético, procesan estos medicamentos más despacio, lo que sube el riesgo de efectos secundarios graves relacionados con la dosis, y por eso revisar la actividad de TPMT antes de empezar el tratamiento es práctica estándar, algo que se explica directamente en la investigación de EII de esta app.",
 "2ddg2mnfpze": "La enfermedad inflamatoria intestinal es un término general para dos padecimientos autoinmunes distintos. La colitis ulcerosa (CU) causa una inflamación continua limitada al colon y al recto; la enfermedad de Crohn puede afectar cualquier parte del tubo digestivo, de la boca al ano, muchas veces en parches, y puede llegar más profundo en la pared del intestino. La diferencia importa directamente, porque varios hallazgos de la investigación de EII de esta app, el más llamativo cómo afecta el tabaco a cada enfermedad, van en direcciones distintas, hasta opuestas, según cuál de las dos tenga la persona.",
 "1ehuu4abxty": "La MK-4 y la MK-7 son dos formas de vitamina K2 con estructuras distintas, diferentes de la vitamina K1 de origen vegetal que casi todos obtienen de las hojas verdes. La MK-4 se parece más a la K1 en su estructura y dura mucho menos en el cuerpo, mientras que la MK-7 se mantiene activa más tiempo y tiene más evidencia de ensayos a dosis realistas para un suplemento, y las dos se explican directamente en la investigación de Nutrientes esenciales de esta app que compara ambas formas.",
 "1imac45z4s1": "DASH (Enfoques Dietéticos para Detener la Hipertensión) es un patrón de alimentación específico basado en verduras, frutas, granos integrales y lácteos bajos en grasa, con menos grasa saturada y sodio. Las guías actuales ponen una meta específica de sodio de menos de 2,300 mg al día, con una meta más baja de 1,500 mg para quien ya tiene presión alta. Es distinta de la dieta mediterránea, aunque las dos son patrones de comida entera con base vegetal, con respaldo propio de ensayos cardiovasculares, y no enfoques que compiten, algo que se explica directamente en la investigación de Enfermedad cardiovascular de esta app.",
 "1nzrldf9p7q": "SCOBY son las siglas en inglés de cultivo simbiótico de bacterias y levaduras, el cultivo iniciador que se usa para fermentar té endulzado y convertirlo en kombucha. La comunidad suele incluir especies de Acetobacter, varias levaduras y muchas veces Gluconobacter, una comunidad mixta y no el enfoque en una sola cepa de casi todas las demás entradas sobre alimentos fermentados de esta app. Como la fermentación del azúcar por levaduras siempre produce algo de etanol como subproducto, también por eso la kombucha tiene un contenido de alcohol documentado, aunque por lo general pequeño, algo que se explica directamente en la investigación de Recetas de esta app.",
 "1xkza8889o3": "NOVA es un sistema de clasificación de alimentos que los ordena en cuatro grupos según qué tanto y para qué se procesaron en la industria, no solo por su contenido de nutrientes. El grupo 4, \"alimentos ultraprocesados\", abarca productos formulados en la industria con ingredientes que casi nunca se usan en la cocina de casa. La investigación encuentra que este nivel de procesamiento se asocia por sí solo con más mortalidad por todas las causas y más riesgo cardiometabólico, incluso después de ajustar por los nutrientes específicos, evidencia de que el nivel de procesamiento en sí, no solo los ingredientes por separado, podría importar por su cuenta, algo que se explica directamente en la investigación de Estilo de vida y medio ambiente de esta app.",
 "1lsghttg62o": "La terapia CAR-T (células T con receptor quimérico de antígeno) modifica las propias células T del paciente, un tipo de célula inmune, para que ataquen en específico y reinicien el proceso inmune que impulsa su enfermedad. Se creó primero para ciertos cánceres y ahora está en pruebas tempranas en personas para enfermedades reumáticas autoinmunes, entre ellas la artritis reumatoide y el lupus. Los datos de todo este enfoque para enfermedades autoinmunes siguen siendo, en su enorme mayoría, de etapa temprana (cerca del 64% de los ensayos todavía en fase 1), algo que se explica directamente en la investigación de Artritis reumatoide de esta app.",
 "odbysupb8k": "PNPLA3 es una variante genética específica relacionada con el riesgo de MASLD (hígado graso). Tener la variante por sí sola sube el riesgo de forma medible, pero combinarla con alcohol, obesidad o diabetes lo aumenta todavía bastante más, un ejemplo documentado de interacción entre genes y ambiente, no de que la genética sola decida el resultado. La investigación encuentra que los cambios de dieta (mediterránea o baja en grasa) funcionan igual de bien sin importar el genotipo de PNPLA3, algo que se explica directamente en la investigación de Hígado graso de esta app.",
 "1zi93upmlqx": "Un monitor continuo de glucosa (MCG) mide la glucosa en la sangre todo el tiempo a lo largo del día, en lugar de con una sola toma de sangre o un análisis de laboratorio. Esto hace práctico seguir el Tiempo en Rango (TIR), el porcentaje del día dentro de una ventana segura de glucosa, una medida más nueva y complementaria que detecta subidas y bajadas peligrosas que un promedio de HbA1c de tres meses por sí solo puede esconder. Las guías actuales buscan por lo menos 70% del tiempo en rango, lo que equivale más o menos al mismo control que representa una HbA1c de 7%, algo que se explica directamente en la investigación de Diabetes tipo 1 de esta app.",
 "srb3fafpnc": "Los TRAb (anticuerpos contra el receptor de TSH) y las TSI (inmunoglobulinas estimulantes de la tiroides) son anticuerpos que se unen al mismo receptor que normalmente usa la TSH y lo estimulan, lo que hace que la tiroides produzca hormona de más. Es un mecanismo con una estructura distinta del de los anticuerpos TPO, que atacan y destruyen poco a poco el tejido tiroideo, y por eso la enfermedad de Graves se comporta tan distinto de Hashimoto aunque las dos sean padecimientos tiroideos autoinmunes. Medir los niveles con el tiempo ayuda a predecir la remisión y la recaída, algo que se explica directamente en la investigación de Enfermedad de Graves de esta app.",
 "onwo7vkc6p": "El DDT es un pesticida creado para controlar enfermedades en tiempos de guerra que pasó a la agricultura general después de 1945, y luego se prohibió en Estados Unidos en 1972 tras un daño ecológico bien documentado (Primavera silenciosa de Rachel Carson, 1962). Su historia, adoptado y confiado por todos y después revertido cuando el daño quedó claro, se repite como un patrón del que se vale directamente la investigación de Industria alimentaria e historia de esta app al hablar de otros ingredientes y prácticas de la industria con una forma parecida.",
 "c4ztxdad0i": "El DAS28 y el CDAI son las dos herramientas más usadas para calificar la actividad de la artritis reumatoide. El CDAI es un conteo puramente clínico (revisión de articulaciones más las evaluaciones generales del paciente y del médico) que no necesita análisis, mientras que el DAS28 también toma en cuenta un marcador de inflamación en la sangre, la VSG o la PCR. Un estudio grande de validación encontró que las dos herramientas son válidas y están muy correlacionadas en general, pero que no coinciden en qué categoría de actividad (remisión, baja, moderada, alta) cae el mismo paciente una parte importante de las veces, algo que se explica directamente en la investigación de Artritis reumatoide de esta app.",
 "1bgzjq35aau": "Un intervalo de confianza (IC) es el rango dentro del cual probablemente cae el efecto de un estudio, que se reporta junto a un número principal (por ejemplo \"72% menos probabilidad, IC del 95% de 0.088 a 0.883\") y no en lugar de él. Un intervalo estrecho indica una estimación más precisa; uno amplio, sobre todo uno que se estira cerca del punto donde el efecto desaparecería por completo, indica un hallazgo hecho con una muestra más chica o con más ruido, que vale la pena tomar como una pista y no como algo resuelto. Esta app dice directamente el intervalo de confianza de un estudio donde cambia de forma importante con cuánta confianza se debe leer un hallazgo.",
 "2eki3ivzbin": "Una biometría hemática completa (BHC) mide los glóbulos rojos, los glóbulos blancos y las plaquetas, un perfil de uso general y no uno hecho para un solo padecimiento. Puede detectar anemia, una infección o un efecto secundario de un medicamento que un perfil de laboratorio de un solo padecimiento pasaría por alto, y se explica directamente en la investigación de esta app sobre abogar por uno mismo como una de las pruebas que vale la pena hacerse con regularidad como base."
};
